const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const { JSDOM } = require('jsdom');

const layout = path.join(__dirname, '..', 'layout');
const read = (file) => fs.readFileSync(path.join(layout, file), 'utf8');

/* Markup of the table generated by ngx-fancyindex (ngx_http_fancyindex_module.c). */
function fancyindexTable(entries, withParent)
{
  const row = (href, name, size, date) =>
    `<tr><td colspan="2" class="link"><a href="${href}" title="${name}">${name}</a></td>` +
    `<td class="size">${size}</td><td class="date">${date}</td></tr>`;

  return '<table id="list"><thead><tr>' +
         '<th colspan="2"><a href="?C=N&amp;O=A">File Name</a>&nbsp;<a href="?C=N&amp;O=D">&nbsp;&darr;&nbsp;</a></th>' +
         '<th><a href="?C=S&amp;O=A">File Size</a>&nbsp;<a href="?C=S&amp;O=D">&nbsp;&darr;&nbsp;</a></th>' +
         '<th><a href="?C=M&amp;O=A">Date</a>&nbsp;<a href="?C=M&amp;O=D">&nbsp;&darr;&nbsp;</a></th>' +
         '</tr></thead><tbody>' +
         (withParent ? row('../', 'Parent directory/', '-', '-') : '') +
         entries.map((entry) => {
           const [href, name] = Array.isArray(entry) ? entry : [entry, entry];
           return row(href, name, '1 KiB', '2024-Sep-12 19:19');
         }).join('') +
         '</tbody></table>';
}

/* Build the page as nginx serves it (header + table + footer), with the theme
 * scripts inlined in place of their <script src> tags. */
async function render(pathname, entries, withParent = pathname != '/')
{
  const header = read('header.html').replace(
    /<script type="text\/javascript" src="\/theme\/js\/(\w+)\.js" defer><\/script>/g,
    (_, name) => `<script>${read(`js/${name}.js`)}</script>`);
  const html = header + fancyindexTable(entries, withParent) + read('footer.html');

  const dom = new JSDOM(html, { url: `http://localhost${pathname}`, runScripts: 'dangerously' });
  await new Promise((resolve) => dom.window.addEventListener('load', resolve));
  return dom.window.document;
}

test('breadcrumbs link every parent directory and end with the current one', async () => {
  const document = await render('/films/2024/', ['a.pdf']);
  const items = [...document.querySelectorAll('#breadcrumbs li')];

  assert.deepEqual(items.map((li) => li.textContent), ['Home', 'films', '2024']);
  assert.deepEqual(items.map((li) => li.querySelector('a')?.getAttribute('href') ?? null),
                   ['/', '/films/', null]);
});

test('breadcrumbs mark the current directory for screen readers', async () => {
  const document = await render('/films/2024/', ['a.pdf']);
  const current = document.querySelector('#breadcrumbs [aria-current="page"]');

  assert.equal(current.textContent, '2024');
  assert.equal(current.className, 'breadcrumb-item active');
});

test('breadcrumbs show directory names as text, never as HTML', async () => {
  const name = '<img src=x onerror=alert(1)>';
  const document = await render(`/${encodeURIComponent(name)}/`, ['a.pdf']);

  assert.equal(document.querySelector('#breadcrumbs img'), null);
  assert.equal(document.querySelector('#breadcrumbs .active').textContent, name);
});

test('a directory name that is not valid UTF-8 does not break the page', async () => {
  const document = await render('/caf%E9/', ['a.pdf']);

  assert.equal(document.querySelector('#breadcrumbs .active').textContent, 'caf%E9');
  assert.ok(document.querySelector('#list i.fa-file-pdf'));
});

test('breadcrumbs show only Home at the root', async () => {
  const document = await render('/', ['a.pdf']);
  assert.deepEqual([...document.querySelectorAll('#breadcrumbs li')].map((li) => li.textContent),
                   ['Home']);
});

test('list gets an icon per file type and drops the parent directory row', async () => {
  const document = await render('/films/', ['sub/', 'doc.PDF', 'notes.txt', 'unknown.xyz']);
  const list = document.getElementById('list');
  const rows = [...list.rows].slice(1);

  assert.deepEqual(rows.map((row) => row.cells[1].textContent),
                   ['sub/', 'doc.PDF', 'notes.txt', 'unknown.xyz']);
  assert.deepEqual(rows.map((row) => row.cells[0].querySelector('i').className),
                   ['fa-solid fa-folder', 'fa-solid fa-file-pdf', 'fa-solid fa-file-text',
                    'fa-solid fa-file']);
  assert.ok(list.classList.contains('table'));
  assert.equal(list.rows[0].cells[0].innerHTML, '');
});

test('list picks the icon from the link when fancyindex truncates the name', async () => {
  const document = await render('/films/', [['a%20very%20long%20report%20name.pdf', 'a very long rep..&gt;']]);
  assert.equal(document.querySelector('#list i').className, 'fa-solid fa-file-pdf');
});

test('list keeps the folder icon when the listing is sorted', async () => {
  const document = await render('/films/', [['sub/?C=N&amp;O=A', 'sub/']]);
  assert.equal(document.querySelector('#list i').className, 'fa-solid fa-folder');
});

test('list keeps all files when fancyindex hides the parent directory row', async () => {
  const document = await render('/films/', ['a.pdf', 'b.mp3'], false);
  assert.deepEqual([...document.getElementById('list').rows].slice(1).map((row) => row.cells[1].textContent),
                   ['a.pdf', 'b.mp3']);
});

test('list works in an empty subdirectory', async () => {
  const document = await render('/films/', []);
  const list = document.getElementById('list');

  assert.equal(list.rows.length, 1);
  assert.ok(list.classList.contains('table'));
});

test('list keeps all rows at the root', async () => {
  const document = await render('/', ['a.pdf', 'b.mp3']);
  const rows = [...document.getElementById('list').rows].slice(1);

  assert.deepEqual(rows.map((row) => row.cells[1].textContent), ['a.pdf', 'b.mp3']);
  assert.deepEqual(rows.map((row) => row.cells[0].querySelector('i').className),
                   ['fa-solid fa-file-pdf', 'fa-solid fa-file-audio']);
});
